320	    @Test
321	    void concurrentFinalFailAndApprovals_neverReleasesRejectedBatch() throws Exception {
322	        String batchKey = "BK-RACE-FAIL-" + unique();
323	        createBatch(batchKey, List.of("t1", "t2"), 201);
324	        submitTest(batchKey, testReq("TK-1", "t1", "PASS", "insp-a"), null, null, 201);
325	
326	        // 同时：最后一项 FAIL、QUALITY 批准、OPERATIONS 批准。行锁按提交顺序串行。
327	        List<Future<Integer>> results = runConcurrent(
328	                () -> callStatus(post("/api/batches/" + batchKey + "/tests")
329	                        .contentType(MediaType.APPLICATION_JSON)
330	                        .content(testReq("TK-2", "t2", "FAIL", "insp-b"))),
331	                () -> callStatus(post("/api/batches/" + batchKey + "/approvals")
332	                        .header("X-Actor-Id", "qa").header("X-Approval-Role", "QUALITY")
333	                        .contentType(MediaType.APPLICATION_JSON).content("{\"commandKey\":\"CA1\"}")),
334	                () -> callStatus(post("/api/batches/" + batchKey + "/approvals")
335	                        .header("X-Actor-Id", "ops").header("X-Approval-Role", "OPERATIONS")
336	                        .contentType(MediaType.APPLICATION_JSON).content("{\"commandKey\":\"CA2\"}"))
337	        );
338	
339	        // 起始为 QUARANTINED：任一批准先获锁都因检验未全部 PASS 返回 422；
340	        // FAIL 提交后批次 REJECTED，后续批准一律 409。绝无失败批次被放行。
341	        assertEquals("REJECTED", currentStatus(batchKey));
342	        Integer approvals = jdbc.queryForObject(
343	                "SELECT COUNT(*) FROM approval WHERE batch_key = ?", Integer.class, batchKey);
344	        assertEquals(0, approvals, "存在 FAIL 的批次不得留下任何批准");
345	        assertEquals(201, results.get(0).get(30, TimeUnit.SECONDS));
346	        assertTrue(results.get(1).get(30, TimeUnit.SECONDS) == 409
347	                || results.get(1).get(30, TimeUnit.SECONDS) == 422);
348	        assertTrue(results.get(2).get(30, TimeUnit.SECONDS) == 409
349	                || results.get(2).get(30, TimeUnit.SECONDS) == 422);
350	    }
