401	    void concurrentRecallAndFinalApproval_cannotReleaseAfterRecall() throws Exception {
402	        String batchKey = "BK-RACE-RC-" + unique();
403	        createBatch(batchKey, List.of("t1"), 201);
404	        submitTest(batchKey, testReq("TK-1", "t1", "PASS", "insp"), null, null, 201);
405	        approve(batchKey, "qa", "QUALITY", "CK-Q", 201);
406	
407	        List<Future<Integer>> results = runConcurrent(
408	                () -> callStatus(post("/api/batches/" + batchKey + "/approvals")
409	                        .header("X-Actor-Id", "ops").header("X-Approval-Role", "OPERATIONS")
410	                        .contentType(MediaType.APPLICATION_JSON).content("{\"commandKey\":\"CK-O\"}")),
411	                () -> callStatus(post("/api/batches/" + batchKey + "/recall")
412	                        .header("X-Actor-Id", "u")
413	                        .contentType(MediaType.APPLICATION_JSON)
414	                        .content("{\"commandKey\":\"CK-R\",\"reason\":\"临检异常\"}"))
415	        );
416	
417	        int secondApproval = results.get(0).get(30, TimeUnit.SECONDS);
418	        int recall = results.get(1).get(30, TimeUnit.SECONDS);
419	        String finalStatus = currentStatus(batchKey);
420	        Integer recallRows = jdbc.queryForObject(
421	                "SELECT COUNT(*) FROM recall WHERE batch_key = ?", Integer.class, batchKey);
422	        if (recallRows > 0) {
423	            // 第二批准先提交为 RELEASED，召回随后提交：终态 RECALLED，绝不可能再被放行
424	            assertEquals(201, secondApproval);
425	            assertEquals(201, recall);
426	            assertEquals("RECALLED", finalStatus);
427	        } else {
428	            // 召回在 RELEASE_REVIEW 阶段先获锁被拒，第二批准随后提交：终态 RELEASED，无召回记录
429	            assertEquals(409, recall);
430	            assertEquals(201, secondApproval);
431	            assertEquals("RELEASED", finalStatus);
432	        }
433	        // 批准历史始终可查，未被召回删除
434	        Integer approvals = jdbc.queryForObject(
435	                "SELECT COUNT(*) FROM approval WHERE batch_key = ?", Integer.class, batchKey);
436	        assertTrue(approvals >= 1);
437	    }
