    public List<String> expireOverdueConditions(String nowIso) {
        List<ConditionRow> overdue = jdbc.query(
                "SELECT * FROM conditional_release c WHERE c.status = 'ACTIVE'"
                        + " AND c.expires_at <= ?"
                        + " AND EXISTS (SELECT 1 FROM condition_item i"
                        + " WHERE i.condition_key = c.condition_key AND i.cleared = 0)"
                        + " ORDER BY c.id FOR UPDATE",
                CONDITION_MAPPER, nowIso);
        List<String> batchKeys = new java.util.ArrayList<>(overdue.size());
        for (ConditionRow row : overdue) {
            updateConditionStatus(row.conditionKey(), "EXPIRED", null);
            batchKeys.add(row.batchKey());
        }
        return batchKeys;
    }
}

